mapper.update:
UPDATE tenant_machine
SET machine_id = #{machineId},
    mac_address = #{macAddress},
    host_name = #{hostName},
    remark = #{remark},
    status = #{status}
WHERE id = #{id}
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM tenant_machine
WHERE id = #{id}
  AND tenant_id = #{tenantId}

mapper.select:
SELECT 
FROM tenant_machine tm
         LEFT JOIN tenant t ON t.id = tm.tenant_id
WHERE tm.id = #{id}
  AND tm.tenant_id = #{tenantId}

SELECT FROM tenant_machine tm LEFT JOIN tenant t ON t.id = tm.tenant_id WHERE tm.tenant_id = #{tenantId}
AND (tm.machine_id LIKE CONCAT('%', #{keyword}, '%') OR tm.mac_address LIKE CONCAT('%', #{keyword}, '%') OR tm.host_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY tm.id DESC LIMIT #{size} OFFSET #{offset}
